## Code Example
```javascript
// Minimal hook sketch
import { useEffect, useRef } from 'react';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { getNavigationRef } from './NavigationService';

function mapPayloadToRoute(p) {
  // implement payload-to-route mapping
  const route = p?.targetRoute;
  return route || null;
}

export function useNotifyNavigate() {
  const nav = getNavigationRef();
  const timer = useRef(null);

  useEffect(() => {
    const onNotify = (payload) => {
      const route = mapPayloadToRoute(payload);
      if (!route) return;
      clearTimeout(timer.current);
      timer.current = setTimeout(async () => {
        const last = await AsyncStorage.getItem('lastRoute');
        if (last === route) return;
        await AsyncStorage.setItem('lastRoute', route);
        nav?.navigate(route);
      }, 150);
    };
    NotificationCenter.addListener('notify', onNotify);
    return () => NotificationCenter.removeListener('notify', onNotify);
  }, [nav]);
}
```

